package course.week10;
import com.sun.net.httpserver.HttpServer;import java.net.*;import java.net.http.HttpClient;import java.time.Duration;import java.nio.charset.StandardCharsets;
public final class Week10Contract {public static void main(String[]a)throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/quote",e->{var b="{\"price\":42}".getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});server.start();try{var x=new SecureQuoteClient(HttpClient.newHttpClient(),Duration.ofSeconds(2));var u=URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/quote");if(!x.fetch(u).equals("{\"price\":42}"))throw new AssertionError("http");var s=x.sign("order-1","secret-key".getBytes(StandardCharsets.UTF_8));if(!s.equals("2ce1510b29a18155aaa07392ac8778b3e7fcd639b6c71c48e8ecea256ded1d76"))throw new AssertionError("hmac "+s);System.out.println("PASS: 2 networking/security behaviors");}finally{server.stop(0);}}}
